3: import * as store from './store.js';
4: 
5: export async function getInvoice(db, params) {
6:   const [invoice] = await store.findInvoice(db, params.invoiceId);
7:   return invoice ? {status:200,body:invoice} : {status:404,body:{error:'missing'}};
8: }
9: export async function postInvoice(db, body) {
10:   await store.insertInvoice(db, body);
11:   for (const line of body.lines || []) await store.insertInvoiceLine(db, body.id, line.sku, line.description, line.quantity, line.unitCents);
12:   await store.repriceInvoice(db, body.id);
13:   return {status:201,body:{id:body.id}};
14: }
15: export async function revenueReport(db, query) {
16:   return {status:200,body:await store.revenueSummary(db, query)};
17: }
18: export async function customerPage(db, query) {
19:   const p = query.page || 0;
20:   return {status:200,body:await store.searchCustomer(db, '%'+(query.q||'')+'%', 25, p*25)};
21: }

